// Add your URLs here, one per line
const urls = [
  "https://www.moroccoworldnews.com/2025/09/259353/moroccos-35-15-billion-green-hydrogen-gamble-ambitious-plans-amid-market-doubts/",
  // Add more URLs here as needed
];

return urls.map(url => ({
  json: {
    article_url: url,
    link: url
  }
}));

// Extract text from HTML and clean it
const inputData = $input.first().json;
let url = inputData.article_url || '';
const htmlRaw = inputData.data || inputData.body || inputData || '';

let htmlString = '';
if (typeof htmlRaw === 'object' && htmlRaw.data) {
    htmlString = htmlRaw.data;
} else if (typeof htmlRaw === 'object') {
    htmlString = JSON.stringify(htmlRaw);
} else {
    htmlString = htmlRaw.toString();
}

// Remove script and style elements
let text = htmlString.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');

// Extract title
let title = '';
const titleMatch = text.match(/<title[^>]*>([^<]*)<\/title>/i);
if (titleMatch) {
    title = titleMatch[1];
} else {
    const h1Match = text.match(/<h1[^>]*>([^<]*)<\/h1>/i);
    if (h1Match) {
        title = h1Match[1];
    }
}

// Clean HTML entities from title
title = title.replace(/&#039;/g, "'");
title = title.replace(/&quot;/g, '"');
title = title.replace(/&amp;/g, '&');
title = title.replace(/&lt;/g, '<');
title = title.replace(/&gt;/g, '>');
title = title.replace(/&[^;]+;/g, ' ');
title = title.replace(/\s+/g, ' ').trim();

// Extract meta description
let description = '';
const descMatch = text.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["']/i);
if (descMatch) {
    description = descMatch[1];
}

// Extract body text
let mainContent = '';
const articlePatterns = [
    /<article[^>]*>([\s\S]*?)<\/article>/i,
    /<div[^>]*class=["'][^"']*content-inner[^"']*["'][^>]*>([\s\S]*?)<\/div>/gi,
    /<div[^>]*class=["'][^"']*entry-content[^"']*["'][^>]*>([\s\S]*?)<\/div>/gi,
    /<div[^>]*class=["'][^"']*article[^"']*["'][^>]*>([\s\S]*?)<\/div>/i,
    /<main[^>]*>([\s\S]*?)<\/main>/i,
    /<div[^>]*id=["']content["'][^>]*>([\s\S]*?)<\/div>/i
];

for (const pattern of articlePatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
        mainContent = match[1];
        break;
    }
}

if (!mainContent) {
    mainContent = text;
}

// Remove all HTML tags
mainContent = mainContent.replace(/<[^>]+>/g, ' ');

// Clean up HTML entities
mainContent = mainContent.replace(/&nbsp;/g, ' ');
mainContent = mainContent.replace(/&amp;/g, '&');
mainContent = mainContent.replace(/&lt;/g, '<');
mainContent = mainContent.replace(/&gt;/g, '>');
mainContent = mainContent.replace(/&quot;/g, '"');
mainContent = mainContent.replace(/&#39;/g, "'");
mainContent = mainContent.replace(/&#039;/g, "'");
mainContent = mainContent.replace(/&[^;]+;/g, ' ');

// Remove extra whitespace
mainContent = mainContent.replace(/\s+/g, ' ');
mainContent = mainContent.trim();

// Limit text length for API (adjusted for GPT-4)
const maxLength = 12000;
if (mainContent.length > maxLength) {
    mainContent = mainContent.substring(0, maxLength) + '...';
}

// Try to get canonical URL if needed
if (!url) {
    const canonicalMatch = text.match(/<link[^>]*rel=["']canonical["'][^>]*href=["']([^"']*)["']/i);
    if (canonicalMatch) {
        url = canonicalMatch[1];
    }
}

return {
    article_url: url || inputData.article_url,
    article_title: title || 'No title found',
    article_text: mainContent || 'No content extracted',
    description: description,
    timestamp: new Date().toISOString(),
    text_length: mainContent.length
};

